Create a custom renderer for the CustomRadioButton class in your platform-specific project (e.g., Android or iOS). This renderer will be responsible for custom

Here's an example Terraform module that uses a `for_each` loop to deploy a federated identity for each service principal and branch specified in the `tfvars` file.

**modules/federated_identity/main.tf**
```terraform
variable "service_principals" {
  type = map(object({
    name     = string
    client_id = string
    tenant_id = string
  }))
}

variable "branches" {
  type = list(string)
}

resource "azurerm_user_assigned_identity" "federated_identity" {
  for_each = var.branches

  resource_group_name = var.resource_group_name
  location           = var.location
  name               = "${var.prefix}-${each.key}-federated-identity"
  sku               = "Standard"
}

resource "azurerm_user_assigned_identity" "service_principal" {
  for_each = var.service_principals

  resource_group_name = var.resource_group_name
  location           = var.location
  name               = "${var.prefix}-${each.key}-service-principal-identity"
  sku               = "Standard"
}

resource "azurerm_federated_identity" "federated_identity" {
  for_each = var.branches

  name                = "${var.prefix}-${each.key}-federated-identity"
  resource_group_name = var.resource_group_name
  location           = var.location
  user_assigned_identity_id = azurerm_user_assigned_identity.federated_identity[each.key].id
  service_principal_ids = [azurerm_user_assigned_identity.service_principal[each.key].id]
}
